mod tests {
    use super::*;

    #[test]
    fn stretch_reads_its_worst_signal() {
        let s = parse_stretch("spread 0.30% A, interference 0.00% B, drift 0.00% A, step 0.00% A");
        assert_eq!(s.letter, 'B');
        assert_eq!(s.signal_letter("drift"), Some('A'));
